function hashString(s, buckets) {
  let h = 0;
  for (let i = 0; i < s.length; i++) {
    h = (h * 31 + s.charCodeAt(i)) % buckets;
  }
  return h;
}

console.log(hashString('a', 8));    // 1
console.log(hashString('ab', 8));   // 1  - a collision
console.log(hashString('abc', 8));  // 2

function makeTable(buckets) {
