function insertProbe(slots, key) {
  const size = slots.length;
  let i = key % size;
  let steps = 0;

  while (slots[i] !== null && steps < size) {
    i = (i + 1) % size;
    steps++;
  }
  if (steps === size) return -1;   // table is full
  slots[i] = key;
  return i;
}

const slots = [null, null, null, null, null];
console.log(insertProbe(slots, 5));   // 0
console.log(insertProbe(slots, 10));  // 1 - displaced by one

