function linearProbeInsert(size, keys) {
  const slots = new Array(size).fill(null);
  const out = [];
  for (const k of keys) {
    let i = k % size;
    let steps = 0;
    while (slots[i] !== null && steps < size) {
      i = (i + 1) % size;
      steps++;
    }
    if (steps === size) { out.push(-1); continue; }
    slots[i] = k;
    out.push(i);
  }
  return out;
}

