function finalBuckets(inserts, initialBuckets, maxLoad) {
  let buckets = initialBuckets, size = 0;
  for (let i = 0; i < inserts; i++) {
    size++;
    if (size / buckets > maxLoad) buckets = buckets * 2;
  }
  return buckets;
}

